// Change these, then save. The other nodes of this workflow read them from here.
const NEWSLETTER_NAME = 'This week in town';
const TO_EMAIL = 'you@example.com'; // where the draft goes for review
const FROM_EMAIL = 'newsletter@example.com';
const MAX_PAGE_CHARS = 12000; // text that goes to the model in one call
const MAX_PAGE_PARTS = 3; // a longer page is split into parts of that size, one call each. Beyond this many parts it is cut: this is what keeps a run cheap.
const MIN_PAGE_CHARS = 200; // a page with less text than this is reported instead of sent to the model (usually a page built by JavaScript)
const LOOKAHEAD_DAYS = 14; // events later than this wait for a later issue
const KEEP_LINKS = true; // keep link addresses in the page text, so events can link to their own page
const LOCALE = 'en'; // language of the day names in the newsletter, e.g. 'de', 'fr', 'es'
const USER_AGENT = 'Mozilla/5.0 (compatible; events-newsletter; n8n)';

return [
  {
    json: {
      newsletter_name: NEWSLETTER_NAME,
      to_email: TO_EMAIL,
      from_email: FROM_EMAIL,
      max_page_chars: MAX_PAGE_CHARS,
      max_page_parts: MAX_PAGE_PARTS,
      min_page_chars: MIN_PAGE_CHARS,
      lookahead_days: LOOKAHEAD_DAYS,
      keep_links: KEEP_LINKS,
      locale: LOCALE,
      user_agent: USER_AGENT,
      today: $now.toFormat('yyyy-MM-dd'), // in the time zone of the workflow
      run_id: String($execution.id),
    },
  },
];

// The rows of the data table newsletter_sources that are switched on.
const rows = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row.url && row.enabled !== false);
if (rows.length === 0) {
  throw new Error('No enabled rows in the data table newsletter_sources. Add the pages that list your events there.');
}
return rows.map((row) => ({ json: { source: String(row.name || row.url).trim(), url: String(row.url).trim() } }));

// Turns each fetched page into plain text. A page longer than MAX_PAGE_CHARS is
// split into parts of at most that size, at most MAX_PAGE_PARTS of them; each
// part later gets its own model call. Only what is beyond the last part is cut.
// One answer per source, in the same order as they were asked.
const S = $('Settings').first().json;
const sources = $('Enabled sources').all();

const NAMED = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '–', mdash: '—', hellip: '…', lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”',
  laquo: '«', raquo: '»', bull: '•', middot: '·', deg: '°', euro: '€', pound: '£', copy: '©', reg: '®', trade: '™', szlig: 'ß',
  agrave: 'à', aacute: 'á', acirc: 'â', atilde: 'ã', auml: 'ä', aring: 'å', aelig: 'æ', ccedil: 'ç', egrave: 'è', eacute: 'é', ecirc: 'ê', euml: 'ë',
  igrave: 'ì', iacute: 'í', icirc: 'î', iuml: 'ï', ntilde: 'ñ', ograve: 'ò', oacute: 'ó', ocirc: 'ô', otilde: 'õ', ouml: 'ö', oslash: 'ø',
  ugrave: 'ù', uacute: 'ú', ucirc: 'û', uuml: 'ü', yacute: 'ý',
};
const decode = (text) =>
  text.replace(/&(#x[0-9a-f]+|#[0-9]+|[a-z]+[0-9]*);/gi, (whole, name) => {
    if (name[0] === '#') {
      const code = name[1].toLowerCase() === 'x' ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10);
      return code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : ' ';
    }
    if (NAMED[name] !== undefined) return NAMED[name];
    // &Eacute; and friends: the capital of a known letter
    const lower = NAMED[name.toLowerCase()];
    return lower !== undefined && name[0] !== name[0].toLowerCase() ? lower.toUpperCase() : whole;
  });

// The Code node has no URL class, so links are resolved by hand.
const absolute = (href, base) => {
  if (/^https?:\/\//i.test(href)) return href;
  const origin = /^(https?:)\/\/[^/?#]+/i.exec(base ?? '');
  if (!origin || !href) return null;
  if (href.startsWith('//')) return origin[1] + href;
  if (/^[a-z][a-z0-9+.-]*:/i.test(href)) return null; // mailto:, tel:, javascript:
  if (href.startsWith('/')) return origin[0] + href;
  const path = base.slice(origin[0].length).replace(/[?#].*$/, '') || '/';
  if (href.startsWith('?') || href.startsWith('#')) return origin[0] + path + href;
  const parts = path.slice(0, path.lastIndexOf('/') + 1).split('/');
  for (const part of href.split('/')) {
    if (part === '..') {
      if (parts.length > 2) parts.splice(-2, 1);
    } else if (part !== '.' && part !== '') parts.splice(-1, 1, part, '');
  }
  return origin[0] + parts.join('/').replace(/\/$/, href.endsWith('/') ? '/' : '');
};

function toText(html, base) {
  // Structured data (schema.org) that many event sites put in a script tag.
  // It is worth keeping: it is often there even when the visible page is
  // built by JavaScript.
  const structured = [];
  for (const match of html.matchAll(/<script\b[^>]*type\s*=\s*["']?application\/ld\+json["']?[^>]*>([\s\S]*?)<\/script>/gi)) {
    if (!/Event/.test(match[1])) continue;
    try {
      structured.push(JSON.stringify(JSON.parse(match[1])));
    } catch {
      structured.push(match[1].replace(/\s+/g, ' ').trim());
    }
  }

  const title = /<title\b[^>]*>([\s\S]*?)<\/title>/i.exec(html)?.[1] ?? '';
  let text = html
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(script|style|svg|template|head|nav|footer|iframe|select)\b[\s\S]*?<\/\1\s*>/gi, ' ');
  if (S.keep_links) {
    text = text.replace(/<a\b[^>]*?href\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))[^>]*>([\s\S]*?)<\/a\s*>/gi, (whole, q, a, b, c, inner) => {
      const href = decode(a ?? b ?? c ?? '').trim();
      const url = href && !href.startsWith('#') ? absolute(href, base) : null;
      return url ? `${inner} [${url}]` : inner;
    });
  }
  text = text
    .replace(/<\/?(td|th)\b[^>]*>/gi, ' | ')
    .replace(/<\/?(p|div|br|li|ul|ol|tr|table|h[1-6]|section|article|header|main|aside|dl|dt|dd|blockquote|pre|hr|figure|figcaption|form)\b[^>]*>/gi, '\n')
    .replace(/<[^>]*>/g, '');
  const lines = [];
  for (const raw of decode(`${title}\n${text}`).split('\n')) {
    const line = raw
      .replace(/\s+/g, ' ')
      .replace(/^(\| ?)+|( ?\|)+$/g, '')
      .replace(/(\| ){2,}/g, '| ')
      .trim();
    if (line && line !== lines[lines.length - 1]) lines.push(line);
  }
  let out = lines.join('\n');
  if (structured.length) out += `\n\nStructured data on the page:\n${structured.join('\n')}`;
  return out;
}

// Splits at the end of a line. Each part starts with the last few lines of the
// part before it, so an event on the border is whole in one of them. The same
// event may then come back twice; it is listed once.
const PART_OVERLAP_LINES = 5;
function split(text, max, maxParts, overlap) {
  const lines = text.split('\n').flatMap((line) => (line.length <= max ? [line] : line.match(new RegExp(`[\\s\\S]{1,${max}}`, 'g'))));
  const parts = [];
  let from = 0;
  let to = 0;
  while (from < lines.length && parts.length < maxParts) {
    let size = 0;
    to = from;
    while (to < lines.length && size + lines[to].length + 1 <= max) {
      size += lines[to].length + 1;
      to += 1;
    }
    parts.push(lines.slice(from, to).join('\n'));
    from = to < lines.length ? Math.max(to - overlap, from + 1) : to;
  }
  return { parts, read_chars: lines.slice(0, to).join('\n').length };
}

return $input.all().map((item, index) => {
  const { source, url } = sources[index].json;
  const answer = item.json;
  const body = typeof answer.body === 'string' ? answer.body : typeof answer.data === 'string' ? answer.data : '';
  const type = String(answer.headers?.['content-type'] ?? '');
  const page = { source, url, ok: false, problem: null, text: '', html_chars: body.length, text_chars: 0, cut: false };

  if (answer.statusCode === undefined) {
    const reason = answer.error?.message ?? answer.error ?? 'no answer';
    page.problem = `could not be fetched (${String(typeof reason === 'string' ? reason : JSON.stringify(reason)).slice(0, 120)})`;
    return { json: page };
  }
  if (answer.statusCode < 200 || answer.statusCode >= 300) {
    page.problem = `answered HTTP ${answer.statusCode}`;
    return { json: page };
  }
  if (type && !/html|xml|text\/plain/i.test(type)) {
    page.problem = `is not a web page (${type.split(';')[0]})`;
    return { json: page };
  }

  const text = toText(body, url);
  page.text_chars = text.length;
  if (text.length < S.min_page_chars) {
    page.problem = `has almost no text in its HTML (${text.length} characters). It is probably built by JavaScript in the browser, which a plain fetch cannot read`;
    return { json: page };
  }
  page.ok = true;
  const { parts, read_chars } = split(text, S.max_page_chars, S.max_page_parts, PART_OVERLAP_LINES);
  page.parts = parts;
  page.text = parts[0];
  page.read_chars = read_chars;
  page.cut = read_chars < text.length;
  return { json: page };
});

// Decides what goes into this issue: no past events, each event once even
// when several sites list it, nothing that an earlier issue already had,
// nothing further away than LOOKAHEAD_DAYS.
const S = $('Settings').first().json;
const pages = $('Page to text').all().map((item) => item.json);
const extracted = ($('Extract events').isExecuted ? $('Extract events').all()[0]?.json : null) ?? { events: [], report: [], sources: [], model_calls: 0, prompt_tokens: 0, completion_tokens: 0 };
const sent = new Set($input.all().map((item) => item.json.event_key).filter(Boolean));

const plain = (text) =>
  String(text)
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, '');
const last = DateTime.fromISO(S.today).plus({ days: S.lookahead_days }).toFormat('yyyy-MM-dd');

const report = [];
for (const page of pages) {
  if (!page.ok) report.push({ source: page.source, url: page.url, level: 'problem', text: `not read: the page ${page.problem}` });
  else if (page.cut) {
    report.push({
      source: page.source,
      url: page.url,
      level: 'note',
      text: `long page: only the first ${page.read_chars.toLocaleString('en')} of ${page.text_chars.toLocaleString('en')} characters were read (${page.parts.length} ${page.parts.length === 1 ? 'call' : 'calls'} of up to ${S.max_page_chars.toLocaleString('en')}). Events further down are missing; point the source at a shorter page or raise MAX_PAGE_PARTS`,
    });
  }
}
report.push(...extracted.report);

const counts = { found: extracted.events.length, past: 0, duplicates: 0, already_sent: 0, later: 0 };
const byKey = new Map();
for (const event of extracted.events) {
  if (event.date < S.today) {
    counts.past += 1;
    continue;
  }
  const key = `${event.date}|${plain(event.title)}`;
  const same = byKey.get(key);
  if (same) {
    // The same event on a second site: keep the first, fill its gaps.
    counts.duplicates += 1;
    for (const field of ['time', 'venue', 'summary']) same[field] = same[field] ?? event[field];
    if (!same.also_on.includes(event.source) && event.source !== same.source) same.also_on.push(event.source);
    continue;
  }
  byKey.set(key, { ...event, event_key: key, also_on: [] });
}

const new_events = [];
const later = [];
for (const event of byKey.values()) {
  if (sent.has(event.event_key)) counts.already_sent += 1;
  else if (event.date > last) later.push(event);
  else new_events.push(event);
}
counts.later = later.length;
const order = (a, b) => `${a.date} ${a.time ?? '99'} ${a.title}`.localeCompare(`${b.date} ${b.time ?? '99'} ${b.title}`);
new_events.sort(order);
later.sort(order);

return [
  {
    json: {
      today: S.today,
      new_events,
      later,
      counts,
      report,
      pages: pages.length,
      pages_read: extracted.sources.filter((entry) => entry.read).length,
      model_calls: extracted.model_calls,
      prompt_tokens: extracted.prompt_tokens,
      completion_tokens: extracted.completion_tokens,
    },
  },
];

// Builds the newsletter from a fixed template. No model is involved here, so
// the layout is the same every week and costs nothing. Change the HTML below
// to match your own newsletter.
const S = $('Settings').first().json;
const issue = $input.first().json;

const esc = (text) => String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const day = (date) => DateTime.fromISO(date).setLocale(S.locale).toFormat('cccc d LLLL');
const FONT = "font-family:Helvetica,Arial,sans-serif";

// --- the newsletter -----------------------------------------------------------
const days = [];
for (const event of issue.new_events) {
  if (days[days.length - 1]?.date !== event.date) days.push({ date: event.date, events: [] });
  days[days.length - 1].events.push(event);
}
const eventHtml = (event) =>
  [
    '<tr><td style="padding:0 0 18px 0">',
    `<div style="${FONT};font-size:17px;line-height:24px;font-weight:bold;color:#111111">${event.url ? `<a href="${esc(event.url)}" style="color:#111111;text-decoration:underline">${esc(event.title)}</a>` : esc(event.title)}</div>`,
    `<div style="${FONT};font-size:14px;line-height:20px;color:#555555">${esc([event.time, event.venue].filter(Boolean).join(' · ') || ' ')}</div>`,
    event.summary ? `<div style="${FONT};font-size:15px;line-height:22px;color:#222222;padding-top:4px">${esc(event.summary)}</div>` : '',
    '</td></tr>',
  ].join('');
const body = days.length
  ? days
      .map((group) =>
        [
          `<tr><td style="${FONT};font-size:13px;line-height:18px;letter-spacing:1px;text-transform:uppercase;color:#888888;border-top:1px solid #dddddd;padding:18px 0 10px 0">${esc(day(group.date))}</td></tr>`,
          ...group.events.map(eventHtml),
        ].join(''),
      )
      .join('')
  : `<tr><td style="${FONT};font-size:15px;line-height:22px;color:#222222;padding:18px 0">No new events this week.</td></tr>`;

const newsletter = [
  '<!doctype html>',
  '<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">',
  `<title>${esc(S.newsletter_name)}</title></head>`,
  '<body style="margin:0;padding:0;background:#f4f4f4">',
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f4"><tr><td align="center" style="padding:24px 12px">',
  '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff"><tr><td style="padding:28px 28px 12px 28px">',
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">',
  `<tr><td style="${FONT};font-size:26px;line-height:32px;font-weight:bold;color:#111111;padding:0 0 18px 0">${esc(S.newsletter_name)}</td></tr>`,
  body,
  '</table>',
  '</td></tr></table>',
  '</td></tr></table>',
  '</body></html>',
].join('\n');

// --- the notes for you, on top of the draft mail --------------------------------
const problems = issue.report.filter((line) => line.level === 'problem');
const notes = issue.report.filter((line) => line.level !== 'problem');
const c = issue.counts;
const line = (entry) => `<li><b>${esc(entry.source)}</b>: ${esc(entry.text)} (<a href="${esc(entry.url)}">${esc(entry.url)}</a>)</li>`;
const review = [
  `<div style="${FONT};font-size:14px;line-height:21px;color:#111111;background:#fff8e1;border:1px solid #e0c36a;padding:16px 20px;margin:0 0 24px 0">`,
  '<p style="margin:0 0 8px 0"><b>DRAFT for review. Nothing was sent to subscribers.</b> The newsletter without this box is attached as an HTML file.</p>',
  `<p style="margin:0 0 8px 0">${issue.new_events.length} new ${issue.new_events.length === 1 ? 'event' : 'events'} from ${issue.pages_read} of ${issue.pages} pages. Left out: ${c.duplicates} listed twice, ${c.already_sent} already in an earlier issue, ${c.past} in the past, ${c.later} more than ${S.lookahead_days} days away.</p>`,
  problems.length ? `<p style="margin:0 0 4px 0"><b>To check (${problems.length}):</b></p><ul style="margin:0 0 8px 0;padding-left:20px">${problems.map(line).join('')}</ul>` : '<p style="margin:0 0 8px 0">Every page was read.</p>',
  notes.length ? `<p style="margin:0 0 4px 0">Notes:</p><ul style="margin:0 0 8px 0;padding-left:20px">${notes.map(line).join('')}</ul>` : '',
  `<p style="margin:0;color:#555555">Model use this run: ${issue.model_calls} ${issue.model_calls === 1 ? 'call' : 'calls'}, ${issue.prompt_tokens.toLocaleString('en')} input tokens, ${issue.completion_tokens.toLocaleString('en')} output tokens.</p>`,
  '</div>',
].join('\n');

const subject = `[DRAFT] ${S.newsletter_name}, ${issue.today}: ${issue.new_events.length} new${problems.length ? `, ${problems.length} to check` : ''}`;
const fileName = `newsletter-${issue.today}.html`;

return [
  {
    json: {
      ...issue,
      run_id: S.run_id,
      to: S.to_email,
      from: S.from_email,
      subject,
      file_name: fileName,
      newsletter_html: newsletter,
      draft_html: newsletter.replace(/(<body[^>]*>)/, `$1\n${review}`),
    },
    binary: {
      newsletter: { data: Buffer.from(newsletter, 'utf8').toString('base64'), mimeType: 'text/html', fileName, fileExtension: 'html' },
    },
  },
];

// One row per event that went into the draft, so later issues leave it out.
const issue = $('Render newsletter').first().json;
return issue.new_events.map((event) => ({
  json: { event_key: event.event_key, title: event.title, event_date: event.date, source: event.source, run_id: issue.run_id, sent_at: $now.toISO() },
}));

// The draft could not be delivered. Nothing is remembered, so the same
// events are in the next run.
const error = $input.first().json.error;
return [{ json: { delivery_failed: true, reason: String(error?.message ?? error ?? 'unknown error').slice(0, 300) } }];

// What this run did, for the data table newsletter_runs and for whoever called.
const issue = $('Render newsletter').first().json;
const failed = $input.first().json.delivery_failed === true;
return [
  {
    json: {
      run_id: issue.run_id,
      ran_at: $now.toISO(),
      delivered: !failed,
      delivery_error: failed ? $input.first().json.reason : null,
      subject: issue.subject,
      pages: issue.pages,
      pages_read: issue.pages_read,
      events_found: issue.counts.found,
      events_new: issue.new_events.length,
      titles: issue.new_events.map((event) => event.title),
      duplicates: issue.counts.duplicates,
      already_sent: issue.counts.already_sent,
      past: issue.counts.past,
      later: issue.counts.later,
      problems: issue.report.filter((entry) => entry.level === 'problem').length,
      report: issue.report,
      model_calls: issue.model_calls,
      prompt_tokens: issue.prompt_tokens,
      completion_tokens: issue.completion_tokens,
    },
  },
];
